#include <stddef.h>
#include <string.h>

static int is_known_type(const char *type, size_t len)
{
    static const char *const types[] = {
        "feat", "fix", "docs", "style", "refactor", "test", "chore"
    };
    size_t i;

    for (i = 0; i < sizeof(types) / sizeof(types[0]); ++i) {
        if (strlen(types[i]) == len && strncmp(types[i], type, len) == 0) {
            return 1;
        }
    }
    return 0;
}

int check_commit_message(const char *msg)
{
    const char *p;
    const char *type;
    const char *scope;
    const char *close;
    size_t type_len;

    if (msg == NULL || msg[0] == '\0') {
        return -1;
    }

    /* 类型字段：从首字符开始，直到 '(' 或 ':' 为止 */
    type = msg;
    p = msg;
    while (*p != '\0' && *p != '(' && *p != ':') {
        ++p;
    }
    type_len = (size_t)(p - type);

    /* 可选范围：类型后紧跟的一对圆括号 */
    if (*p == '(') {
        scope = p + 1;
        close = strchr(scope, ')');

        if (close == NULL) {
            return -2;              /* 括号未闭合，视为缺少 ": " 分隔符 */
        }
        if (close == scope) {
            return -5;              /* 范围为空 */
        }
        p = close + 1;
    }

    /* 分隔符必须是 ": "（冒号后紧跟一个空格） */
    if (p[0] != ':' || p[1] != ' ') {
        return -2;
    }

    if (!is_known_type(type, type_len)) {
        return -3;
    }

    p += 2;
    if (*p == '\0') {
        return -4;                  /* 描述为空 */
    }

    return 0;
}
